using System.Windows;using System.Windows.Controls;using FFPerformanceEngine.Core.Models;namespace FFPerformanceEngine.App.Pages;public partial class ProfilesPage:UserControl{private IReadOnlyList<PerformanceProfile> _profiles=Array.Empty<PerformanceProfile>();public ProfilesPage(){InitializeComponent();Loaded+=OnLoaded;}private async void OnLoaded(object s,RoutedEventArgs e){_profiles=await App.Services.Profiles.LoadAsync();ProfilesList.ItemsSource=_profiles;var recommended=_profiles.FirstOrDefault(x=>x.Kind==ProfileKind.Recommended);RecommendedText.Text=recommended is null?"Ainda não há um perfil Recomendado validado.":$"{recommended.AverageFps:0} FPS · 1% Low {recommended.OnePercentLow:0} · confiança {recommended.Confidence:P0}";}private async void ApplyProfile_Click(object s,RoutedEventArgs e){if(s is not Button{Tag:Guid id})return;var p=_profiles.FirstOrDefault(x=>x.Id==id);if(p is null)return;await App.Services.History.AppendAsync(new HistoryEvent{Kind=HistoryEventKind.Profile,Title="Perfil selecionado",Summary=$"{p.Name} selecionado. Alterações RestartRequired permanecem pendentes até uma aplicação segura."});MessageBox.Show($"Perfil {p.Name} selecionado. Esta versão só aplica automaticamente mudanças classificadas como seguras; alterações de instância permanecem para Optimize/Expert.","FF Performance Engine");}}